class Solution:
    def zigZagArrays(self, n: int, l: int, r: int) -> int:
        MOD = 10**9 + 7
        m = r - l + 1
        if n == 2:
            return m * (m - 1) % MOD
        inc = list(range(m))
        for _ in range(n - 2):
            pre = [0] * (m + 1)
            for i in range(m):
                pre[i + 1] = (pre[i] + inc[i]) % MOD
            tot = pre[m]
            inc = [(tot - pre[m - j]) % MOD for j in range(m)]
        return 2 * sum(inc) % MOD

