class Solution {
public:
    int zigZagArrays(int n, int l, int r) {
        const long long MOD = 1e9 + 7;
        long long m = r - l + 1;
        if (n == 2) return m % MOD * ((m - 1) % MOD) % MOD;
        vector<long long> inc(m);
        for (long long j = 0; j < m; j++) inc[j] = j % MOD;
        for (int k = 2; k < n; k++) {
            vector<long long> pre(m + 1, 0);
            for (long long i = 0; i < m; i++) pre[i + 1] = (pre[i] + inc[i]) % MOD;
            long long tot = pre[m];
            vector<long long> nxt(m);
            for (long long j = 0; j < m; j++)
                nxt[j] = ((tot - pre[m - j]) % MOD + MOD) % MOD;
            inc = move(nxt);
        }
        long long ans = 0;
        for (long long v : inc) ans = (ans + v) % MOD;
        return ans * 2 % MOD;
    }
};

