class Solution:
    def zigZagArrays(self, n: int, l: int, r: int) -> int:
        MOD = 10**9 + 7
        m = r - l + 1
        if n == 2:
            return m * (m - 1) % MOD
        N = n + 1
        ys = []
        for s in range(1, N + 1):
            inc = list(range(s))
            for _ in range(n - 2):
                pre = [0] * (s + 1)
                for i in range(s):
                    pre[i + 1] = (pre[i] + inc[i]) % MOD
                tot = pre[s]
                inc = [(tot - pre[s - j]) % MOD for j in range(s)]
            ys.append(2 * sum(inc) % MOD)
        if m <= N:
            return ys[m - 1]
        pref = [1] * (N + 1)
        suf = [1] * (N + 1)
        for i in range(N):
            pref[i + 1] = pref[i] * ((m - (i + 1)) % MOD) % MOD
        for i in range(N - 1, -1, -1):
            suf[i] = suf[i + 1] * ((m - (i + 1)) % MOD) % MOD
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD
        ans = 0
        for i in range(N):
            num = pref[i] * suf[i + 1] % MOD
            den = fact[i] * fact[N - 1 - i] % MOD
            ans = (ans + ys[i] * num % MOD * pow(den, MOD - 2, MOD)) % MOD
        return ans

