var zigZagArrays = function(n, l, r) {
    const MOD = 1000000007n, B = BigInt;
    const pw = (b, e) => { let res = 1n; b %= MOD;
        while (e > 0n) { if (e & 1n) res = res * b % MOD; b = b * b % MOD; e >>= 1n; } return res; };
    let m = B(r - l + 1);
    if (n === 2) return Number(m % MOD * ((m - 1n) % MOD) % MOD);
    const N = n + 1, ys = [];
    for (let s = 1; s <= N; s++) {
        let inc = [];
        for (let j = 0; j < s; j++) inc.push(B(j));
        for (let k = 2; k < n; k++) {
            let pre = [0n];
            for (const v of inc) pre.push((pre[pre.length - 1] + v) % MOD);
            const tot = pre[s];
            inc = [];
            for (let j = 0; j < s; j++)
                inc.push(((tot - pre[s - j]) % MOD + MOD) % MOD);
        }
        let t = 0n;
        for (const v of inc) t = (t + v) % MOD;
        ys.push(t * 2n % MOD);
    }
    if (m <= B(N)) return Number(ys[Number(m) - 1]);
    let pref = [1n], suf = [1n], fact = [1n];
    for (let i = 0; i < N; i++) pref.push(pref[i] * ((m - B(i + 1)) % MOD) % MOD);
    for (let i = 0; i < N; i++) suf.unshift(suf[0] * ((m - B(N - i)) % MOD) % MOD);
    for (let i = 1; i <= N; i++) fact.push(fact[i - 1] * B(i) % MOD);
    let ans = 0n;
    for (let i = 0; i < N; i++) {
        const num = pref[i] * suf[i + 1] % MOD;
        const den = fact[i] * fact[N - 1 - i] % MOD;
        ans = (ans + ys[i] * num % MOD * pw(den, MOD - 2n)) % MOD;
    }
    return Number(ans);
};
